import React, { useState, useEffect } from 'react';
import './Jubilacion.css'; 
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const Jubilacion = () => {
    const [data, setData] = useState([]);  
    const [loading, setLoading] = useState(true);  
    const apiKey = 'c80584cb38-3c1fd2f449-sk8eb7';  

    const fetchExchangeRateData = async () => {
        try {
            const response = await fetch(
                `https://api.fastforex.io/time-series?from=USD&to=MXN&interval=P1D&api_key=${apiKey}`
            );
            const result = await response.json();

            const transformedData = Object.keys(result.results.MXN).map(date => ({
                date: date,
                value: result.results.MXN[date],
            }));

            setData(transformedData);  
            setLoading(false);  
        } catch (error) {
            console.error('Error fetching exchange rate data:', error);
            setLoading(false);  
        }
    };

    useEffect(() => {
        fetchExchangeRateData();
    }, []);

    const handleBuy = () => {
        alert('Comprar acción iniciada');
    };

    const handleSell = () => {
        alert('Vender acción iniciada');
    };

    const handlePrediction = () => {
        alert('Predicción de moneda mostrada');
    };

    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda</h1>
            <div className="jubilacion-content">
                <p>Este gráfico muestra el precio del dólar frente al peso mexicano (MXN).</p>
                
                {/* Botón "Ver predicción" */}
                <div className="prediction-button-container">
                    <button className="action-button" onClick={handlePrediction}>Ver predicción</button>
                </div>

                {loading ? (
                    <p>Cargando datos...</p>
                ) : (
                    <ResponsiveContainer width="100%" height={400}>
                        <LineChart data={data}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis dataKey="date" />
                            <YAxis ticks={[12, 18, 24]} domain={[12, 24]} />
                            <Tooltip />
                            <Line type="monotone" dataKey="value" stroke="#007bff" />
                        </LineChart>
                    </ResponsiveContainer>
                )}

                {/* Botones de Comprar y Vender debajo de la gráfica */}
                <div className="button-container">
                    <button className="action-button" onClick={handleBuy}>Comprar</button>
                    <button className="action-button" onClick={handleSell}>Vender</button>
                </div>
            </div>
        </div>
    );
};

export default Jubilacion;
